// План specs/support.md, 1.2 (кейс SUP-02). Admin в Support Console. Только чтение: не отвечать, не нажимать «Close Chat». @prod-safe
import { test, expect } from '@playwright/test';
import { ADMIN_STATE, expectAllStamps, openInboxChat, openTicketDetail, setEnglish } from './support-helpers';

test.use({ storageState: ADMIN_STATE, timezoneId: 'Asia/Jerusalem' });

test.describe('Поддержка — дата и время сообщений (#3db49a08)', () => {
  test('Support Console shows DD/MM/YY HH:mm on the chat header and on every message #3db49a08 @desktop @prod-safe', async ({ page }) => {
    await setEnglish(page);

    // Шаг 1: Support Console → вкладка Chat → QA-обращение; шапка «Chat · Customer: … · DD/MM/YY HH:mm»
    await openInboxChat(page);
    const inbox = await expectAllStamps(page);

    // Те же сообщения на экране обращения — те же метки
    await openTicketDetail(page);
    const detail = await expectAllStamps(page);
    for (const [dt, text] of Object.entries(inbox)) {
      if (dt in detail) expect(detail[dt], `сообщение ${dt}`).toBe(text);
    }
    expect(Object.keys(inbox).filter((dt) => dt in detail).length).toBeGreaterThanOrEqual(5);
  });
});
